export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

import type { ReactNode } from "react";

/* Markdown subset for chat replies. Text keeps its source offset so streaming can tell new
   words from old; unclosed ** and ` run to the line's end so markers never flash. */

export type Inline = { kind: "text" | "strong" | "code"; start: number; text: string };
export type Line = { start: number; pieces: Inline[] };
export type Block =
  | { kind: "p"; start: number; lines: Line[] }
  | { kind: "ul" | "ol"; start: number; first: number; items: { start: number; lines: Line[] }[] };

const BULLET = /^(\s*)([-*•])\s+/;
const NUMBER = /^(\s*)(\d{1,4})[.)]\s+/;

function parseInline(text: string, base: number): Line {
  return { start: base, pieces: parsePieces(text, base) };
}

function parsePieces(text: string, base: number): Inline[] {
  const out: Inline[] = [];
  let i = 0;
  let plain = "";
  let plainStart = base;
  const flush = () => {
    if (plain) out.push({ kind: "text", start: plainStart, text: plain });
    plain = "";
  };
  while (i < text.length) {
    const marker = text.startsWith("**", i) ? "**" : text[i] === "`" ? "`" : null;
    if (!marker) {
      if (!plain) plainStart = base + i;
      plain += text[i++];
      continue;
    }
    const open = i + marker.length;
    const close = text.indexOf(marker, open);
    const end = close === -1 ? text.length : close;
    flush();
    if (end > open) out.push({ kind: marker === "`" ? "code" : "strong", start: base + open, text: text.slice(open, end) });
    i = close === -1 ? text.length : close + marker.length;
  }
  flush();
  return out;
}

export function parse(source: string): Block[] {
  const blocks: Block[] = [];
  let current = null as Block | null;
  let offset = 0;

  for (const raw of source.split("\n")) {
    const lineStart = offset;
    offset += raw.length + 1;

    if (!raw.trim()) {
      current = null;
      continue;
    }
    const bullet = BULLET.exec(raw);
    const number = bullet ? null : NUMBER.exec(raw);
    const marker = bullet ?? number;

    if (marker) {
      const kind = bullet ? "ul" : "ol";
      const content = raw.slice(marker[0].length);
      const item = { start: lineStart, lines: [parseInline(content, lineStart + marker[0].length)] };
      if (current?.kind === kind) current.items.push(item);
      else {
        current = { kind, start: lineStart, first: number ? Number(number[2]) : 1, items: [item] };
        blocks.push(current);
      }
      continue;
    }

    // An indented line under a list item continues that item.
    if (current && current.kind !== "p" && /^\s/.test(raw)) {
      const lead = raw.length - raw.trimStart().length;
      current.items.at(-1)!.lines.push(parseInline(raw.trimStart(), lineStart + lead));
      continue;
    }

    if (current?.kind === "p") current.lines.push(parseInline(raw, lineStart));
    else {
      current = { kind: "p", start: lineStart, lines: [parseInline(raw, lineStart)] };
      blocks.push(current);
    }
  }
  return blocks;
}

/** Text to React children; streaming wraps new words. */
export type RenderText = (text: string, start: number) => ReactNode;

const plainText: RenderText = (text) => text;

function renderLines(lines: Line[], renderText: RenderText, tail: ReactNode) {
  return lines.map((line, n) => (
    <span key={line.start}>
      {n > 0 && <br />}
      {line.pieces.map((piece) => {
        const content = renderText(piece.text, piece.start);
        if (piece.kind === "code") return <code key={piece.start}>{content}</code>;
        if (piece.kind === "strong") return <strong key={piece.start}>{content}</strong>;
        return <span key={piece.start}>{content}</span>;
      })}
      {n === lines.length - 1 && tail}
    </span>
  ));
}

/** Renders parsed blocks; `tail` goes right after the newest word. */
export function renderBlocks(blocks: Block[], renderText: RenderText = plainText, tail: ReactNode = null) {
  return blocks.map((block, b) => {
    const blockTail = b === blocks.length - 1 ? tail : null;
    if (block.kind === "p") return <p key={block.start}>{renderLines(block.lines, renderText, blockTail)}</p>;
    const items = block.items.map((item, i) => (
      <li key={item.start}>{renderLines(item.lines, renderText, i === block.items.length - 1 ? blockTail : null)}</li>
    ));
    return block.kind === "ul" ? (
      <ul key={block.start}>{items}</ul>
    ) : (
      <ol key={block.start} start={block.first === 1 ? undefined : block.first}>
        {items}
      </ol>
    );
  });
}

@layer theme, base, components, utilities;

.pending {
  composes: sweep from "../text/text.module.css";
}

.fileName {
  composes: wrap from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* Thread */

  .thread {
    position: relative;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    min-height: 0;
    height: 100%;
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
  }

  .scroller {
    /* Containing block for visually hidden status text, so it can't stretch the page. */
    position: relative;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
    outline: none;
  }

  .scroller {
    border-radius: inherit;
  }

  .scroller:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .content {
    display: flex;
    flex-direction: column;
    max-width: var(--message-thread-width, 680px);
    min-height: 100%;
    margin-inline: auto;
    padding: var(--ui-space-5) var(--ui-space-4) var(--ui-space-6);
  }

  .empty {
    display: grid;
    flex: 1;
    place-items: center;
    text-align: center;
  }

  /* Messages */

  .message {
    display: grid;
    min-width: 0;
  }

  .message + .message {
    margin-top: var(--ui-space-6);
  }

  .message[data-from="user"] + .message[data-from="assistant"] {
    margin-top: var(--ui-space-5);
  }

  .message[data-avatar] {
    --avatar: 28px;
    grid-template-columns: var(--avatar) minmax(0, 1fr);
    gap: var(--ui-space-3);
  }

  .message[data-from="user"][data-avatar] {
    grid-template-columns: minmax(0, 1fr) var(--avatar);
  }

  .message[data-from="user"][data-avatar] .avatar {
    order: 1;
    margin-top: calc(var(--ui-space-3) + (var(--ui-leading-md) - var(--avatar)) / 2);
  }

  .avatar {
    display: grid;
    place-items: center;
    width: var(--avatar);
    height: var(--avatar);
    margin-top: calc((var(--ui-text-md) * var(--ui-leading-prose) - var(--avatar)) / 2);
    overflow: hidden;
    border-radius: var(--ui-radius-full);
    background: var(--ui-fill);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
  }

  .avatar > img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .main {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }

  .message[data-from="user"] .main {
    align-items: flex-end;
    gap: var(--ui-space-2);
  }

  .message[data-from="user"][data-enter] .main {
    animation: message-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes message-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }

  .bubble {
    max-width: min(85%, 520px);
    padding: var(--ui-space-3) var(--ui-space-4);
    border-radius: var(--ui-radius-lg);
    background: var(--ui-fill);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  .prose {
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-prose);
    hanging-punctuation: first;
    overflow-wrap: break-word;
  }

  .prose > * {
    margin: 0;
  }

  .prose > * + * {
    margin-top: var(--ui-space-3);
  }

  .prose > p + :is(ul, ol) {
    margin-top: var(--ui-space-1);
  }

  .prose > :is(ul, ol) + p {
    margin-top: var(--ui-space-4);
  }

  .prose ul,
  .prose ol {
    padding-inline-start: 22px;
  }

  .prose li + li {
    margin-top: var(--ui-space-1);
  }

  .prose li {
    padding-inline-start: 2px;
  }

  .prose li::marker {
    color: var(--ui-subtle);
    font-variant-numeric: tabular-nums;
  }

  .prose strong {
    font-weight: var(--ui-weight-medium);
  }

  .prose code {
    padding: 2px 5px;
    border-radius: calc(var(--ui-radius-sm) / 2);
    background: var(--ui-fill);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-code);
  }

  .word {
    animation: word-in var(--ui-dur-base) var(--ui-ease-enter) backwards;
    animation-delay: var(--delay, 0ms);
  }

  @keyframes word-in {
    from {
      opacity: 0;
    }
  }

  .pending {
    --sweep-dim: 0.45;
    color: var(--ui-muted);
  }

  /* Stopped and error */

  .note {
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    margin: var(--ui-space-3) 0 0;
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
  }

  .note svg {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    fill: currentColor;
  }

  .error {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ui-space-2) var(--ui-space-3);
    margin-top: var(--ui-space-3);
  }

  .message[data-status="error"] .prose:has(p) + .error {
    padding-top: var(--ui-space-3);
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  .error p {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    margin: 0;
    color: var(--ui-danger-text);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .error svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    margin-top: calc((var(--ui-leading-md) - 16px) / 2);
    flex-shrink: 0;
  }

  /* Attachments on a sent message */

  .attachments {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--ui-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .attachment {
    position: relative;
    border-radius: var(--ui-radius-md);
  }

  .attachment[data-kind="image"] img {
    display: block;
    width: 96px;
    height: 96px;
    border-radius: inherit;
    background: var(--ui-fill);
    object-fit: cover;
  }

  .attachment[data-kind="image"]::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border);
    pointer-events: none;
  }

  .attachment[data-kind="file"] {
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
    max-width: 240px;
    height: var(--ui-control-md);
    padding-inline: var(--ui-space-3);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .attachment[data-kind="file"] svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke);
    stroke-linejoin: round;
  }

  /* Actions */

  .actions {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    display: flex;
    align-items: center;
    gap: 2px;
    min-height: var(--ui-control-sm);
    /* 16px under the reply, the same everywhere actions follow a message:
       clear of the last line's descenders, still read as part of it. */
    margin-top: var(--ui-space-4);
    /* Pull the first icon's ink in line with the text above. */
    margin-inline-start: -8px;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Space stays reserved while streaming, so finishing doesn't push anything. */
  .actions[data-hidden] {
    visibility: hidden;
  }

  /* Hover can't be the only way to an action: touch and the latest reply always show them. */
  @media (hover: hover) and (pointer: fine) {
    .actions:not([data-pinned]) {
      opacity: 0;
    }
    .message:hover .actions,
    .actions:focus-within,
    .message:last-child .actions {
      opacity: 1;
    }
  }

  .action {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--ui-control-sm);
    height: var(--ui-control-sm);
    padding-inline: var(--ui-space-2);
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    isolation: isolate;
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* No clip on the button, so a label morphing into "Copied" is never cut off. */
  .action::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .action svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke);
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: fill var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .action:hover {
      color: var(--ui-foreground);
    }
    .action:hover::before {
      background: var(--ui-fill);
    }
  }

  .action:active::before {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .action:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .action[aria-pressed="true"] {
    color: var(--ui-foreground);
  }

  .action[aria-pressed="true"] svg {
    fill: currentColor;
  }

  .action[data-copy="copied"] {
    color: var(--ui-foreground);
  }

  .action[data-copy="failed"] {
    color: var(--ui-danger-text);
  }

  .actionLabel {
    display: inline-flex;
  }

  @media (pointer: coarse) {
    .action {
      min-width: var(--ui-control-md);
      height: var(--ui-control-md);
    }
    .actions {
      margin-inline-start: -12px;
    }
  }

  /* Jump to latest */

  .jump {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    position: absolute;
    bottom: var(--ui-space-4);
    left: 50%;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: var(--ui-control-sm);
    padding-inline: 10px 14px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong), var(--ui-shadow-raised);
    color: var(--ui-foreground);
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    touch-action: manipulation;
    translate: -50% 4px;
    opacity: 0;
    visibility: hidden;
    /* visibility takes it out of the tab order once gone. */
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      translate var(--ui-dur-instant) var(--ui-ease-exit),
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .jump[data-visible] {
    translate: -50% 0;
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      translate var(--ui-dur-fast) var(--ui-ease-enter),
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s;
  }

  /* arrow-right rotated, so its hover nudge points down. */
  .jump .jumpArrow {
    width: 14px;
    height: 14px;
    rotate: 90deg;
  }

  @media (hover: hover) {
    .jump:hover {
      background: var(--ui-fill-solid);
    }
  }

  .jump:active {
    background: var(--ui-fill-strong-solid);
    transition-duration: var(--ui-dur-press);
  }

  .jump:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .jump::before {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .word,
    .message[data-from="user"][data-enter] .main {
      animation: none;
    }
    .jump {
      translate: -50% 0;
    }
    .action::before {
      transition-property: background-color;
    }
    .action:active::before {
      scale: none;
    }
  }
}

"use client";

import {
  Children,
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Button } from "../button/button";
import { TextMorph } from "../text-morph/text-morph";
import { Icon } from "../icons/icons";
import { StreamingText } from "./streaming-text";
import { useStickToBottom } from "./use-stick-to-bottom";
import styles from "./message-thread.module.css";

export { StreamingText } from "./streaming-text";

export type MessageStatus = "complete" | "streaming" | "stopped" | "error";
export type Feedback = "up" | "down" | null;
export type MessageAttachment = { name: string; url?: string; type?: string; size?: number };

// Only messages mounted after the first paint animate in; history doesn't replay.
const ReadyContext = createContext(false);

type MessageThreadProps = Omit<ComponentProps<"div">, "children"> & {
  children?: ReactNode;
  /** Accessible name of the log. */
  label?: string;
  empty?: ReactNode;
};

export function MessageThread({ children, label = "Conversation", empty, className, ...props }: MessageThreadProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const { showJump, jumpToLatest } = useStickToBottom(scrollRef, contentRef);
  const [ready, setReady] = useState(false);
  // `{cond && list}` passes false; only real children count.
  const isEmpty = Children.toArray(children).length === 0;

  useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  return (
    <div className={className ? `${styles.thread} ${className}` : styles.thread} {...props}>
      <div
        ref={scrollRef}
        className={styles.scroller}
        role="log"
        aria-live="polite"
        aria-relevant="additions"
        aria-label={label}
        // Focusable so the conversation can be scrolled from the keyboard.
        tabIndex={0}
      >
        <div ref={contentRef} className={styles.content} data-empty={isEmpty || undefined}>
          <ReadyContext value={ready}>{isEmpty ? <div className={styles.empty}>{empty}</div> : children}</ReadyContext>
        </div>
      </div>
      <button
        type="button"
        className={styles.jump}
        data-visible={showJump || undefined}
        inert={!showJump}
        onClick={() => {
          jumpToLatest();
          scrollRef.current?.focus({ preventScroll: true });
        }}
      >
        <Icon className={styles.jumpArrow} name="arrow-right" />
        Jump to latest
      </button>
    </div>
  );
}

type MessageProps = {
  from: "user" | "assistant";
  /** Markdown-ish text; streams in place. */
  text?: string;
  /** Pre-rendered content; wins over `text`. */
  children?: ReactNode;
  status?: MessageStatus;
  /** Accessible author label. Defaults to "You" / "Assistant". */
  author?: string;
  /** An avatar element (an <img>, initials); none by default. */
  avatar?: ReactNode;
  attachments?: MessageAttachment[];
  /** What went wrong, for status="error". */
  error?: string;
  onRetry?: () => void;
  feedback?: Feedback;
  onFeedback?: (value: Feedback) => void;
  /** Text the Copy action copies. Defaults to `text`. */
  copyText?: string;
  /** The row under an assistant reply. Default: Copy, Retry and thumbs. `false`
   *  leaves it out; a node (such as `<ResponseActions />`) replaces it. */
  actions?: ReactNode | false;
  className?: string;
};

export function Message({
  from,
  text = "",
  children,
  status = "complete",
  author = from === "user" ? "You" : "Assistant",
  avatar,
  attachments,
  error = "Something went wrong before the reply finished.",
  onRetry,
  feedback,
  onFeedback,
  copyText,
  actions,
  className,
}: MessageProps) {
  const ready = useContext(ReadyContext);
  const [enter] = useState(ready);
  const streaming = status === "streaming";

  let body: ReactNode;
  if (from === "user") {
    body = (children ?? text) ? <div className={styles.bubble}>{children ?? text}</div> : null;
  } else if (children) {
    body = (
      <div key={streaming ? "live" : "done"} className={styles.prose} aria-hidden={streaming || undefined}>
        {children}
      </div>
    );
  } else {
    body = <StreamingText text={text} streaming={streaming} />;
  }

  return (
    <article
      className={className ? `${styles.message} ${className}` : styles.message}
      data-from={from}
      data-status={status}
      data-enter={enter || undefined}
      data-avatar={avatar ? true : undefined}
      aria-label={author}
      aria-busy={streaming || undefined}
    >
      {avatar && <div className={styles.avatar}>{avatar}</div>}
      <div className={styles.main}>
        {attachments && attachments.length > 0 && <Attachments items={attachments} />}
        {body}
        {status === "stopped" && (
          <p className={styles.note}>
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <rect x="4.5" y="4.5" width="7" height="7" rx="1.5" />
            </svg>
            You stopped this reply.
          </p>
        )}
        {status === "error" && (
          <div className={styles.error}>
            <p>
              <svg viewBox="0 0 16 16" aria-hidden="true">
                <circle cx="8" cy="8" r="6.25" fill="none" stroke="currentColor" />
                <path d="M8 4.75v3.75" stroke="currentColor" strokeLinecap="round" />
                <circle cx="8" cy="11" r="0.9" fill="currentColor" />
              </svg>
              {error}
            </p>
            {onRetry && (
              <Button variant="secondary" onClick={onRetry}>
                Retry
              </Button>
            )}
          </div>
        )}
        {from === "assistant" && status !== "error" && actions !== undefined && actions !== false && actions}
        {from === "assistant" && status !== "error" && actions === undefined && (
          <MessageActions
            hidden={streaming}
            copyText={copyText ?? text}
            onRetry={onRetry}
            feedback={feedback}
            onFeedback={onFeedback}
          />
        )}
      </div>
    </article>
  );
}

function Attachments({ items }: { items: MessageAttachment[] }) {
  return (
    <ul className={styles.attachments} aria-label="Attachments">
      {items.map((item, i) =>
        item.url && item.type?.startsWith("image/") ? (
          <li key={i} className={styles.attachment} data-kind="image">
            {/* eslint-disable-next-line @next/next/no-img-element -- user uploads, sizes are fixed */}
            <img src={item.url} alt={item.name} width={96} height={96} draggable={false} />
          </li>
        ) : (
          <li key={i} className={styles.attachment} data-kind="file">
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d="M9.25 2H5a1.25 1.25 0 0 0-1.25 1.25v9.5A1.25 1.25 0 0 0 5 14h6a1.25 1.25 0 0 0 1.25-1.25V5L9.25 2Z" />
              <path d="M9.25 2v3h3" />
            </svg>
            <span className={styles.fileName} title={item.name}>
              {item.name}
            </span>
          </li>
        ),
      )}
    </ul>
  );
}

type MessageActionsProps = {
  /** Reserve the row's space without showing it (while streaming). */
  hidden?: boolean;
  copyText: string;
  onRetry?: () => void;
  feedback?: Feedback;
  onFeedback?: (value: Feedback) => void;
};

function MessageActions({ hidden, copyText, onRetry, feedback, onFeedback }: MessageActionsProps) {
  const [copy, setCopy] = useState<"idle" | "copied" | "failed">("idle");
  const [innerFeedback, setInnerFeedback] = useState<Feedback>(null);
  const current = feedback !== undefined ? feedback : innerFeedback;
  const timer = useRef(0);

  useEffect(() => () => clearTimeout(timer.current), []);

  async function handleCopy() {
    clearTimeout(timer.current);
    try {
      if (!navigator.clipboard) throw new Error("Clipboard unavailable");
      await navigator.clipboard.writeText(copyText);
      setCopy("copied");
    } catch {
      setCopy("failed");
    }
    timer.current = window.setTimeout(() => setCopy("idle"), 2000);
  }

  function rate(value: "up" | "down") {
    const next = current === value ? null : value;
    if (feedback === undefined) setInnerFeedback(next);
    onFeedback?.(next);
  }

  return (
    <div
      className={styles.actions}
      data-hidden={hidden || undefined}
      data-pinned={copy !== "idle" || current ? true : undefined}
      inert={hidden}
    >
      <button type="button" className={styles.action} data-copy={copy} aria-label="Copy" onClick={handleCopy}>
        <Icon name={copy === "copied" ? "check" : "copy"} />
        <span className={styles.actionLabel} aria-hidden="true">
          <TextMorph>{copy === "copied" ? " Copied" : copy === "failed" ? " Couldn’t copy" : ""}</TextMorph>
        </span>
      </button>
      {onRetry && (
        <button type="button" className={styles.action} aria-label="Retry" onClick={onRetry}>
          <svg viewBox="0 0 16 16" aria-hidden="true">
            <path d="M2.75 8a5.25 5.25 0 1 0 1.6-3.78" />
            <path d="M2.75 2.75v3h3" />
          </svg>
        </button>
      )}
      <button
        type="button"
        className={styles.action}
        aria-label="Good response"
        aria-pressed={current === "up"}
        onClick={() => rate("up")}
      >
        <ThumbIcon />
      </button>
      <button
        type="button"
        className={styles.action}
        aria-label="Bad response"
        aria-pressed={current === "down"}
        onClick={() => rate("down")}
      >
        <ThumbIcon down />
      </button>
      <span role="status" className={styles.srOnly}>
        {copy === "copied" ? "Copied" : copy === "failed" ? "Couldn’t copy. Select the text instead." : ""}
      </span>
    </div>
  );
}

function ThumbIcon({ down }: { down?: boolean }) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" style={down ? { rotate: "180deg" } : undefined}>
      <path d="M5.25 7.25 7.6 2.5c.95 0 1.65.85 1.5 1.8l-.35 2.2h3.05a1.4 1.4 0 0 1 1.37 1.7l-.95 4.2a1.4 1.4 0 0 1-1.37 1.1H5.25Z" />
      <path d="M5.25 7.25h-1.5a1 1 0 0 0-1 1v4.5a1 1 0 0 0 1 1h1.5Z" />
    </svg>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { parse, renderBlocks, type RenderText } from "./markdown";
import styles from "./message-thread.module.css";

/* Animate by source offset, not mount order, so a word moving into a new parent doesn't
   replay. The aria-hidden animated tree becomes plain text at the end. */

type Batch = { from: number; to: number; at: number };
type View = { text: string; batches: Batch[] };

// Must cover the entrance (--ui-dur-base) plus the largest stagger, with room.
const BATCH_LIFE = 1000;
const MAX_STAGGER = 180;

function wholeWords(text: string, streaming: boolean) {
  if (!streaming) return text;
  for (let i = text.length - 1; i >= 0; i--) {
    if (/\s/.test(text[i])) return text.slice(0, i + 1);
  }
  return "";
}

function advance(prev: View, text: string, streaming: boolean, now: number): View {
  const next = wholeWords(text, streaming);
  if (next === prev.text) return prev;
  // Replaced, not extended (a regenerate): start over without animating.
  if (!next.startsWith(prev.text)) return { text: next, batches: [] };
  const batches = prev.batches.filter((b) => now - b.at < BATCH_LIFE);
  batches.push({ from: prev.text.length, to: next.length, at: now });
  return { text: next, batches };
}

const WORD = /\S+\s*|\s+/g;

function animatedText(batches: Batch[]): RenderText {
  return (text, start) => {
    if (!batches.length || start + text.length <= batches[0].from) return text;
    const out: ReactNode[] = [];
    let plain = "";
    for (const match of text.matchAll(WORD)) {
      const from = start + match.index;
      const to = from + match[0].length;
      const batch = batches.find((b) => to > b.from && to <= b.to);
      if (!batch) {
        plain += match[0];
        continue;
      }
      if (plain) out.push(plain);
      plain = "";
      const delay = Math.min(Math.max(0, from - batch.from) * 3, MAX_STAGGER);
      out.push(
        <span key={from} className={styles.word} style={{ "--delay": `${delay}ms` } as CSSProperties}>
          {match[0]}
        </span>,
      );
    }
    if (plain) out.push(plain);
    return out;
  };
}

type StreamingTextProps = {
  /** The reply so far. */
  text: string;
  streaming: boolean;
  /** Read to screen readers while the reply streams. */
  pendingLabel?: string;
  className?: string;
};

export function StreamingText({ text, streaming, pendingLabel = "Writing a reply…", className }: StreamingTextProps) {
  const [view, setView] = useState<View>(() => ({ text: wholeWords(text, streaming), batches: [] }));
  const [settledText, setSettledText] = useState<string | null>(streaming ? null : text);
  const latest = useRef({ text, streaming });
  const frame = useRef(0);

  // Coalesce updates to one per frame.
  useEffect(() => {
    latest.current = { text, streaming };
    if (frame.current) return;
    frame.current = requestAnimationFrame(() => {
      frame.current = 0;
      const { text, streaming } = latest.current;
      setView((prev) => advance(prev, text, streaming, performance.now()));
    });
  }, [text, streaming]);

  useEffect(
    () => () => {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    },
    [],
  );

  useEffect(() => {
    if (streaming) return;
    const timer = setTimeout(() => setSettledText(text), BATCH_LIFE);
    return () => clearTimeout(timer);
  }, [streaming, text]);

  const live = streaming || settledText !== text;
  const shown = live ? view.text : text;
  const blocks = useMemo(() => parse(shown), [shown]);
  const classes = className ? `${styles.prose} ${className}` : styles.prose;

  if (!live) {
    return (
      <div key="done" className={classes}>
        {renderBlocks(blocks)}
      </div>
    );
  }

  return (
    <>
      <div key="live" className={classes} data-streaming="" aria-hidden="true">
        {blocks.length ? renderBlocks(blocks, animatedText(view.batches)) : <p className={styles.pending}>Thinking</p>}
      </div>
      {streaming && <span className={styles.srOnly}>{pendingLabel}</span>}
    </>
  );
}

"use client";

import { useCallback, useLayoutEffect, useRef, useState, type RefObject } from "react";

/* Pin in the ResizeObserver callback (before paint) so no frame shows the old position.
   Keep overflow-anchor on: it holds what the user reads still. */

const STICK_DISTANCE = 8;
const SHOW_JUMP_DISTANCE = 64;

export function useStickToBottom(
  scrollRef: RefObject<HTMLElement | null>,
  contentRef: RefObject<HTMLElement | null>,
) {
  const stuck = useRef(true);
  const jumping = useRef(false);
  const [showJump, setShowJump] = useState(false);

  useLayoutEffect(() => {
    const scroller = scrollRef.current;
    const content = contentRef.current;
    if (!scroller || !content) return;

    const distance = () => scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight;
    const pin = () => {
      scroller.scrollTop = scroller.scrollHeight;
    };
    const sync = () => setShowJump(!stuck.current && distance() > SHOW_JUMP_DISTANCE);
    const release = () => {
      if (!stuck.current && !jumping.current) return;
      stuck.current = false;
      jumping.current = false;
      sync();
    };

    pin();

    const resize = new ResizeObserver(() => {
      if (stuck.current && !jumping.current) pin();
      sync();
    });
    resize.observe(content);
    resize.observe(scroller);

    // A message the user just sent always brings them to the bottom.
    const mutations = new MutationObserver((records) => {
      for (const record of records) {
        for (const node of record.addedNodes) {
          if (node instanceof HTMLElement && node.dataset.from === "user") {
            stuck.current = true;
            jumping.current = false;
            pin();
            sync();
            return;
          }
        }
      }
    });
    mutations.observe(content, { childList: true });

    let touchY = 0;
    const onWheel = (e: WheelEvent) => {
      if (e.deltaY < 0) release();
    };
    const onTouchStart = (e: TouchEvent) => {
      touchY = e.touches[0].clientY;
    };
    const onTouchMove = (e: TouchEvent) => {
      const y = e.touches[0].clientY;
      if (y > touchY + 2) release();
      touchY = y;
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowUp" || e.key === "PageUp" || e.key === "Home" || (e.key === " " && e.shiftKey)) release();
    };
    // Growth below can fire a scroll before the next pin, so distance alone
    // isn't the reader leaving: only a move up (a scrollbar drag, find in
    // page) lets go. Wheel, touch and keys release above.
    let lastTop = scroller.scrollTop;
    const onScroll = () => {
      const d = distance();
      const movedUp = scroller.scrollTop < lastTop - 1;
      lastTop = scroller.scrollTop;
      if (jumping.current) {
        if (d <= 1) {
          jumping.current = false;
          stuck.current = true;
        }
      } else if (d <= STICK_DISTANCE) {
        stuck.current = true;
      } else if (stuck.current && movedUp) {
        stuck.current = false;
      } else if (stuck.current) {
        pin();
      }
      sync();
    };
    // The smooth jump aimed at the old bottom; finish any growth instantly.
    const onScrollEnd = () => {
      if (!jumping.current) return;
      jumping.current = false;
      stuck.current = true;
      pin();
      sync();
    };

    scroller.addEventListener("wheel", onWheel, { passive: true });
    scroller.addEventListener("touchstart", onTouchStart, { passive: true });
    scroller.addEventListener("touchmove", onTouchMove, { passive: true });
    scroller.addEventListener("keydown", onKeyDown);
    scroller.addEventListener("scroll", onScroll, { passive: true });
    scroller.addEventListener("scrollend", onScrollEnd);
    return () => {
      resize.disconnect();
      mutations.disconnect();
      scroller.removeEventListener("wheel", onWheel);
      scroller.removeEventListener("touchstart", onTouchStart);
      scroller.removeEventListener("touchmove", onTouchMove);
      scroller.removeEventListener("keydown", onKeyDown);
      scroller.removeEventListener("scroll", onScroll);
      scroller.removeEventListener("scrollend", onScrollEnd);
    };
  }, [scrollRef, contentRef]);

  const jumpToLatest = useCallback(() => {
    const scroller = scrollRef.current;
    if (!scroller) return;
    const smooth = !matchMedia("(prefers-reduced-motion: reduce)").matches;
    stuck.current = true;
    jumping.current = smooth;
    setShowJump(false);
    scroller.scrollTo({ top: scroller.scrollHeight, behavior: smooth ? "smooth" : "auto" });
    // Browsers without scrollend: settle after the smooth scroll would be done.
    if (smooth && !("onscrollend" in window)) {
      setTimeout(() => {
        if (!jumping.current) return;
        jumping.current = false;
        scroller.scrollTop = scroller.scrollHeight;
      }, 700);
    }
  }, [scrollRef]);

  return { showJump, jumpToLatest };
}
